'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={kind:'feedback',tab:'attention',product:'',q:'',rating:0,sort:'oldest',offset:0,limit:12,rows:[],selected:null,dirty:false,settings:null,section:'automation',knowledge:null,campaigns:null,proposals:null,productKnowledge:'DR-01',campaign:'seasonal-warm',proposal:null,previewReview:null};
async function api(path,method='GET',body){const opts={method,headers:{}};if(body!==undefined){opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(body)}const r=await fetch(path,opts);const data=await r.json().catch(()=>({}));if(!r.ok)throw new Error(typeof data.detail==='string'?data.detail:JSON.stringify(data.detail||data));return data}
function qs(obj){return new URLSearchParams(Object.entries(obj).filter(([,v])=>v!==undefined&&v!==null)).toString()}
function notify(message,error=false){const n=$('#notice');n.textContent=message;n.className=error?'error':'';n.hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>n.hidden=true,7000)}
async function attempt(action){try{await action()}catch(e){notify(e.message,true)}}
function productName(p){return p?`${p.name} · ${p.color}`:'Товар не сопоставлен'}
function stars(n){return `<span class="rating-cell" aria-label="${n} из 5 звёзд">${'★'.repeat(n)}<i>${'★'.repeat(5-n)}</i></span>`}
function date(s){if(!s)return '—';let d=typeof s==='number'?new Date(s*1000):new Date(s);return Number.isNaN(d.valueOf())?'—':d.toLocaleDateString('ru-RU',{day:'2-digit',month:'2-digit',year:'numeric'})}
function reason(r){if(r.model_status==='running')return 'ИИ готовит ответ';if(r.model_status==='pending')return 'ИИ ожидает запуска';if(r.model_status==='retry')return r.reason||'Повтор ИИ запланирован';if(r.model_status==='limit')return r.reason||'Лимит ИИ исчерпан';if(r.model_status==='failed')return r.reason||'ИИ не подготовил ответ';return r.reason||r.defer_reason||({'new':'В обработке','ready_auto':'Автоответ','api_confirmed':state.mode==='demo'?'Локальная имитация Demo':'Подтверждено чтением WB','deferred':'Отложено','failed':'Ошибка'}[r.status]||r.status)}
function setView(view){$('#queue-view').hidden=view!=='queue';$('#settings-view').hidden=view!=='settings'}
async function loadQueue(preserve=true){const seq=state.queueRequest=(state.queueRequest||0)+1;let old=state.selected?.id;const [data,summary]=await Promise.all([api('/api/v2/state?'+qs({kind:state.kind,tab:state.tab,product_id:state.product,q:state.q,rating:state.rating,sort:state.sort,offset:state.offset,limit:state.limit})),api('/api/v4/summary?'+qs({kind:state.kind,product_id:state.product}))]);if(seq!==state.queueRequest)return;state.summary=summary;state.rows=data.reviews;state.total=data.total;state.counts=data.counts;state.variants=data.variants;state.processing=data.processing_enabled;state.auto=data.auto_send_enabled;state.mode=data.mode;renderQueue();renderTop();if(preserve&&old&&data.reviews.some(x=>x.id===old))await selectReview(old,false);else if(data.reviews.length)await selectReview(data.reviews[0].id,false);else{state.selected=null;$('#detail').innerHTML='<div class="empty">В этой вкладке нет обращений</div>'}}
function renderTop(){const active=state.processing&&state.auto;$('#automation-status').textContent=active?'Автоотправка: по правилам':state.processing?'Автоотправка выключена':'Автообработка на паузе';$('#automation-status').classList.toggle('off',!active);$('#auto-pause').textContent=state.processing?'Пауза':'Возобновить';$('#mode-badge').textContent=state.mode==='sandbox'?'WB Sandbox':'Demo'}
function renderQueue(){const c=state.counts;const summary=$('#summary-line');summary.innerHTML=`${esc(state.summary.period)}: получено <strong>${state.summary.received}</strong> · автоматически <strong>${state.summary.auto_sent}</strong> · менеджером <strong>${state.summary.manager_sent}</strong> · на проверке <strong>${state.summary.attention}</strong> · в обработке <strong>${state.summary.processing}</strong>`;const product=$('#queue-product');const previous=state.product;product.innerHTML='<option value="">Все товары</option>'+state.variants.map(v=>`<option value="${esc(v.product.product_id)}">${esc(productName(v.product))} · ${v.counts[state.tab]||0}</option>`).join('');product.value=previous;$$('.queue-tabs button').forEach(b=>{b.classList.toggle('active',b.dataset.tab===state.tab);b.querySelector('b').textContent=c[b.dataset.tab]||0});$('#queue-hint').textContent=state.tab==='attention'?'Показаны обращения, которые система не отправила автоматически':state.tab==='processing'?'Система подготавливает и проверяет ответы':state.tab==='done'?'Ответы с подтверждённым результатом':'Обращения выбранной категории';$('#queue-list').innerHTML=state.rows.map(r=>{let p=r.product;let text=[r.body,r.pros,r.cons].filter(Boolean).join(' · ');return `<button type="button" class="queue-row ${state.selected?.id===r.id?'selected':''}" data-id="${esc(r.id)}" role="listitem"><span class="product-cell">${p?`<img src="${esc(p.photo)}" alt=""><span>${esc(p.name)}<small>${esc(p.color)}</small></span>`:'Товар?'}</span><span class="buyer-cell"><strong>${esc(r.user_name||'Покупатель')}</strong><small>${date(r.created_date||r.updated_at)}</small></span><span>${r.kind==='feedback'?stars(r.rating):'<small>Вопрос</small>'}</span><span class="excerpt">${esc(text||'Без текста')} ${r.photo_urls?.length?`<span class="photo-count">📷 ${r.photo_urls.length}</span>`:''}</span><span class="reason-cell">${esc(reason(r))}</span></button>`}).join('')||'<div class="empty">Нет обращений по этим фильтрам</div>';const page=Math.floor(state.offset/state.limit)+1;const pages=Math.max(1,Math.ceil(state.total/state.limit));$('#queue-page-info').textContent=`${state.total?state.offset+1:0}–${Math.min(state.offset+state.limit,state.total)} из ${state.total}`;$('#page-numbers').innerHTML=`Страница ${page} из ${pages}`;$('#prev-page').disabled=state.offset===0;$('#next-page').disabled=state.offset+state.limit>=state.total;$$('.queue-row').forEach(b=>b.onclick=()=>attempt(()=>selectReview(b.dataset.id,true)))}
async function selectReview(id,mobile){if(state.dirty&&state.selected?.id!==id){if(!confirm('Сохранить правку перед переходом к другому обращению?'))return;await saveDraft()}const seq=state.detailRequest=(state.detailRequest||0)+1;const row=await api('/api/v2/reviews/'+encodeURIComponent(id));if(seq!==state.detailRequest)return;state.selected=row;state.dirty=false;renderDetail();$$('.queue-row').forEach(b=>b.classList.toggle('selected',b.dataset.id===id));if(mobile&&innerWidth<=900)$('#queue-layout').dataset.mobileView='detail'}
function renderDetail(){let r=state.selected;if(!r)return;let p=r.product;const index=state.rows.findIndex(x=>x.id===r.id)+1;let canEdit=['needs_review','ready_auto','deferred'].includes(r.status);let photos=(r.photo_urls||[]).map((src,i)=>`<button type="button" data-photo="${i}" aria-label="Открыть фото покупателя ${i+1}"><img src="${esc(src)}" alt="Фото покупателя ${i+1}"></button>`).join('');let facts=(r.facts_used||[]).map(x=>`<li><strong>${esc(x.field)}: ${esc(x.value)}</strong><small>${esc(x.source)} · версия ${x.version}</small></li>`).join('');if(r.scenario_ground)facts+=`<li><strong>Сценарий ${esc(r.scenario_ground.id)} · v${r.scenario_ground.version}</strong><small>Помощь: ${esc(r.scenario_ground.action)}</small><small>Основание: ${esc(r.scenario_ground.source)}</small></li>`;$('#detail').innerHTML=`<div class="detail-scroll"><div class="detail-top"><button class="mobile-back" id="mobile-back" type="button">← Очередь</button><h2>${r.kind==='question'?'Вопрос':'Отзыв'} ${esc(r.id)}</h2><span class="counter">${index||'—'} из ${state.total}</span></div><div class="detail-product">${p?`<img src="${esc(p.photo)}" alt="${esc(p.name)}"><span><strong>${esc(r.kind==='question'?p.name+' · '+p.color:productName(p))}</strong><small>Артикул продавца ${esc(p.seller_article)} · ${esc(p.product_id)}${r.kind==='feedback'&&r.remote_size?' · Размер покупки '+esc(r.remote_size):''}</small></span>`:'Товар не сопоставлен'}</div><div class="detail-buyer"><strong>${esc(r.user_name||'Покупатель')}</strong>${r.kind==='feedback'?stars(r.rating):''}<time>${date(r.created_date||r.updated_at)}</time></div><div class="detail-text">${r.body?`<p>${esc(r.body)}</p>`:''}${r.pros?`<p><strong>Достоинства:</strong> ${esc(r.pros)}</p>`:''}${r.cons?`<p><strong>Недостатки:</strong> ${esc(r.cons)}</p>`:''}${!r.body&&!r.pros&&!r.cons?'Без текста':''}</div>${photos?`<div class="photo-strip">${photos}</div>`:''}<div class="reason-banner"><div><strong>${esc(reason(r))}</strong><span>${esc(r.model_status==='running'?'ИИ готовит ответ.':r.model_status==='pending'?'ИИ ожидает запуска.':r.model_status==='retry'?'Повтор ИИ запланирован; черновик сохранён.':r.model_status==='limit'?'Лимит ИИ исчерпан; черновик сохранён.':r.model_status==='failed'?'ИИ не подготовил проверенный ответ; черновик сохранён.':r.status==='needs_review'?'Ответ требует решения менеджера перед отправкой.':r.status==='api_confirmed'?(state.mode==='demo'?'Локальная имитация Demo; WB не вызывался.':'Текст подтверждён чтением WB; видимость после модерации не подтверждена.'):'Статус и текст проверяются перед отправкой.')}</span></div></div>${!r.revision_current?'<button id="refresh-review" type="button">Обновить черновик по текущим правилам</button>':''}<div class="editor-title"><h3>Ответ покупателю</h3><span class="source-pill">${esc(r.generator||'Ожидает подготовки')}</span></div><textarea id="reply-editor" class="reply-editor" maxlength="700" aria-label="Текст ответа покупателю" ${canEdit?'':'disabled'}>${esc(r.draft||r.sent_text||'')}</textarea><div class="editor-meta"><span id="draft-state">${r.revision_current?'Актуальная версия':'Правила изменились · обновите обращение'}</span><span id="char-count">${(r.draft||'').length} / 700</span></div>${canEdit?`<div class="editor-tools"><button id="open-templates" type="button">Готовый ответ</button><button id="rephrase" type="button">Предложить через ИИ</button><button id="save-draft" type="button">Сохранить правку</button></div>`:''}${r.kind==='question'?`<div class="audience"><label for="audience">Аудитория</label><select id="audience" ${canEdit?'':'disabled'}><option value="">Выберите</option><option value="public" ${r.audience==='public'?'selected':''}>Публично в WB</option><option value="private" ${r.audience==='private'?'selected':''}>Лично · только WB Partners</option></select></div><p class="audience-note">Личный ответ через API не отправляется.</p>`:''}<details class="facts"><summary>Основания ответа · ${r.facts_used?.length||0} фактов</summary>${facts?`<ul>${facts}</ul>`:'<p class="micro">У этого ответа нет использованных подтверждённых фактов.</p>'}</details>${r.status==='api_confirmed'?`<div class="status-note">${esc(r.reason||'Отправлено')} · ${esc(r.sent_text||'')}</div>`:''}</div><div class="detail-actions"><span class="footnote">${state.mode==='demo'?'Demo: отправка имитируется локально':'Sandbox: отправка только allowlist'}</span>${canEdit?`<button id="defer" type="button">Отложить</button>${r.kind==='question'&&r.audience==='private'?'<button id="private-copy" type="button">Скопировать для WB Partners</button><a href="https://seller.wildberries.ru/" target="_blank" rel="noopener noreferrer">Открыть WB Partners</a>':''}<button id="send-next" class="primary" type="button" ${r.revision_current&&r.draft&&(r.kind!=='question'||r.audience==='public')?'':'disabled'}>Отправить и следующий →</button>`:'<button id="next-review" class="primary" type="button">Следующий →</button>'}</div>`;
$('#private-copy')?.addEventListener('click',()=>attempt(async()=>{await navigator.clipboard.writeText($('#reply-editor').value);notify('Текст скопирован; отправьте его лично в WB Partners')}));$('#refresh-review')?.addEventListener('click',()=>attempt(async()=>{let x=await api('/api/v4/reviews/'+encodeURIComponent(r.id)+'/refresh','POST',{source_hash:r.source_hash,draft_version:r.draft_version});notify(x.detail);await selectReview(r.id,false)}));$('#mobile-back')?.addEventListener('click',()=>$('#queue-layout').dataset.mobileView='list');$$('[data-photo]').forEach(b=>b.onclick=()=>{let src=r.photo_urls[Number(b.dataset.photo)];$('#photo-full').src=src;$('#photo-dialog').showModal()});$('#reply-editor')?.addEventListener('input',e=>{state.dirty=true;$('#char-count').textContent=e.target.value.length+' / 700';$('#draft-state').textContent='Несохранённая правка';$('#send-next').disabled=!e.target.value.trim()||(r.kind==='question'&&r.audience!=='public')});$('#save-draft')?.addEventListener('click',()=>attempt(saveDraft));$('#open-templates')?.addEventListener('click',()=>attempt(openTemplates));$('#rephrase')?.addEventListener('click',()=>attempt(rephrase));$('#defer')?.addEventListener('click',()=>$('#defer-dialog').showModal());$('#send-next')?.addEventListener('click',()=>attempt(sendNext));$('#next-review')?.addEventListener('click',()=>attempt(nextReview));$('#audience')?.addEventListener('change',e=>attempt(async()=>{let a=await api('/api/v2/reviews/'+encodeURIComponent(r.id)+'/audience','PUT',{audience:e.target.value,source_hash:r.source_hash,revision:r.revision,draft_version:r.draft_version});notify('Аудитория сохранена');await selectReview(r.id,false)}))}
async function saveDraft(){let r=state.selected,text=$('#reply-editor').value;if(!state.dirty)return;const data=await api('/api/v2/reviews/'+encodeURIComponent(r.id)+'/draft','PUT',{text,source_hash:r.source_hash,revision:r.revision,draft_version:r.draft_version});r.draft_version=data.draft_version;r.draft=text;r.generator='Правка менеджера';state.dirty=false;$('#draft-state').textContent='Правка сохранена';notify('Правка сохранена на сервере')}
async function sendNext(){let r=state.selected;const button=$('#send-next');button.disabled=true;try{if(state.dirty)await saveDraft();if(state.selected?.id!==r.id)throw new Error('Открыто другое обращение; проверьте текст перед отправкой');const text=$('#reply-editor').value;const current=await api('/api/v2/reviews/'+encodeURIComponent(r.id));if(current.source_hash!==r.source_hash||current.revision!==r.revision||current.draft!==text)throw new Error('Обращение или черновик изменились; обновите карточку');const body={text,source_hash:current.source_hash,revision:current.revision,draft_version:current.draft_version,audience:current.kind==='question'?current.audience:null};const result=await api('/api/v2/reviews/'+encodeURIComponent(r.id)+'/send','POST',body);if(result.status!=='api_confirmed'){notify(result.detail||'Отправка требует проверки',true);await selectReview(r.id,false);return}notify(state.mode==='demo'?'Ответ имитирован в Demo. Открыт следующий отзыв.':'Ответ подтверждён WB Sandbox. Открыт следующий отзыв.');await loadQueue(false)}finally{button.disabled=false}}
async function nextReview(){let i=state.rows.findIndex(x=>x.id===state.selected.id);if(i>=0&&i+1<state.rows.length)await selectReview(state.rows[i+1].id,false);else if(state.offset+state.limit<state.total){state.offset+=state.limit;await loadQueue(false)}else notify('Вы дошли до конца списка')}
async function rephrase(){const r=state.selected;if(state.dirty)await saveDraft();notify('Hermes готовит ответ…');const x=await api('/api/v2/reviews/'+encodeURIComponent(r.id)+'/rephrase','POST',{text:r.draft||'',source_hash:r.source_hash,revision:r.revision,draft_version:r.draft_version});if(x.status==='ready'){notify('Ответ ИИ проверен и сохранён');await selectReview(r.id,false)}else notify(x.detail||'ИИ недоступен; черновик сохранён',true)}
async function openTemplates(){let x=await api('/api/v2/templates?kind='+state.kind);$('#template-list').innerHTML=x.templates.map(t=>`<div class="template-entry"><button type="button" data-tid="${esc(t.id)}">Вставить</button><strong>${esc(t.name)}</strong><small>${esc(t.intent)} · ${esc(t.body)}</small></div>`).join('');$$('[data-tid]').forEach(b=>b.onclick=()=>attempt(async()=>{let r=state.selected;if(state.dirty)await saveDraft();const x=await api('/api/v2/reviews/'+encodeURIComponent(r.id)+'/template','POST',{template_id:b.dataset.tid,source_hash:r.source_hash,revision:r.revision,draft_version:r.draft_version});$('#template-dialog').close();notify('Шаблон подставлен и сохранён');await selectReview(r.id,false)}));$('#template-dialog').showModal()}
function pick(value,choices){return choices.map(([v,label])=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(label)}</option>`).join('')}
function productOptions(products,value,all=false){return (all?'<option value="">Все товары</option>':'')+products.map(p=>`<option value="${esc(p.product_id)}" ${p.product_id===value?'selected':''}>${esc(productName(p))}</option>`).join('')}
async function showSettings(section='automation'){state.section=section;setView('settings');$$('.settings-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.section===section));$('#settings-title').textContent=({automation:'Настройки автоответов',knowledge:'Знания о товаре и сценарии',upsell:'Сезонные кампании',proposals:'Предложения ИИ'}[section]);$('#settings-content').innerHTML='<div class="empty">Загрузка…</div>';$('#settings-footer').innerHTML='';if(section==='automation')await loadSettings();if(section==='knowledge')await loadKnowledge();if(section==='upsell')await loadCampaigns();if(section==='proposals')await loadProposals()}
async function loadSettings(scope='all',id=''){state.settings=await api('/api/v4/settings?'+qs({scope_type:scope,scope_id:id}));renderSettings()}
function renderSettings(){let s=state.settings,c=s.config;let content=$('#settings-content');content.innerHTML=`<div class="settings-scope"><strong>Применять правила к</strong><select id="rule-scope" aria-label="Область правил"><option value="all">Все товары</option>${[...new Set(s.products.map(p=>p.model_id))].map(m=>`<option value="model:${esc(m)}">Модель ${esc(m)}</option>`).join('')}${s.products.map(p=>`<option value="product:${esc(p.product_id)}">${esc(productName(p))}</option>`).join('')}</select><small>Правило товара перекрывает правило модели, модель — общее правило.</small></div><div class="settings-grid"><section><h2>Подготовка текста</h2><p>Ответ создаёт сервер после получения обращения. Режим определяет источник текста.</p><label class="radio-row"><input type="radio" name="generation" value="templates" ${c.generation_mode==='templates'?'checked':''}><span><strong>Шаблоны</strong><small>Утверждённые тексты и факты товара</small></span></label><label class="radio-row"><input type="radio" name="generation" value="ai" ${c.generation_mode==='ai'?'checked':''}><span><strong>ИИ Hermes</strong><small>Ограниченный дневной бюджет; результат проверяется</small></span></label><label class="radio-row"><input type="radio" name="generation" value="combined" ${c.generation_mode==='combined'?'checked':''}><span><strong>Комбинированный</strong><small>Шаблон для простых случаев, Hermes для остальных</small></span></label><div class="form-row"><label for="tone">Тон</label><select id="tone">${pick(c.tone,[['respectful','Уважительный'],['warm','Тёплый'],['neutral','Нейтральный']])}</select></div><div class="form-row"><label for="length">Длина</label><select id="length">${pick(c.length,[['short','Короткий'],['medium','Средний']])}</select></div><label class="check-row"><input id="use-name" type="checkbox" ${c.use_name?'checked':''}>Обращаться к покупателю по имени, если оно есть</label><div class="form-row"><label for="budget">Лимит ИИ в день</label><input id="budget" type="number" min="1" max="30" value="${c.llm_budget_per_day}"></div><div class="form-row"><label for="cycle-budget">За один цикл</label><input id="cycle-budget" type="number" min="1" max="2" value="${c.llm_max_per_cycle}"></div><p class="micro">Использовано сегодня: ${s.llm_used}. Режим не делает платные вызовы для накопленных Demo отзывов без явного сохранения правил.</p><button id="template-settings" type="button">Открыть шаблоны</button></section><section><h2>Разрешение на отправку</h2><p>Решение об отправке отделено от подготовки текста. Пауза в шапке останавливает фоновую обработку.</p><label class="radio-row"><input type="radio" name="send-mode" value="rules" ${c.send_mode==='rules'?'checked':''}><span><strong>По правилам</strong><small>Только после проверки текста и условий</small></span></label><label class="radio-row"><input type="radio" name="send-mode" value="review_all" ${c.send_mode==='review_all'?'checked':''}><span><strong>Все на проверку</strong><small>Сервер готовит текст, менеджер отправляет вручную</small></span></label><h3>Правила по оценке</h3>${[5,4,3,2,1].map(n=>`<div class="rating-rule"><span>${stars(n)}</span><select data-rating="${n}" aria-label="Действие для ${n} звёзд">${pick(c.rating_actions[String(n)],[['auto','Автоответ'],['review','На проверку']])}</select></div>`).join('')}<h3>Исключения</h3>${[['complaint','Жалоба или негатив в тексте'],['missing_fact','Нет подтверждённого факта'],['personal_size','Личный подбор размера'],['photo_context','Фото требует проверки']].map(([k,l])=>`<label class="check-row"><input data-exception="${k}" type="checkbox" ${c.exceptions[k]?'checked':''} ${k==='photo_context'?'':'disabled'}>${l}${k==='photo_context'?'':' · защитное правило'}</label>`).join('')}<label class="check-row"><input id="only-new" type="checkbox" checked disabled>Только новые обращения после сохранения настроек</label><div class="preview-panel"><strong>Накопленные обращения</strong><p>Отдельно переподготовить до 100 записей за раз только для ручной проверки.</p><button id="backlog-preview" type="button">Показать объём</button><div id="backlog-result"></div></div><div class="info-box">Автоотправка сейчас ${s.auto_send_enabled?'включена':'выключена'}. ${s.processing_enabled?'Подготовка идёт.':'Обработка на паузе.'}</div><button id="toggle-autosend" type="button">${s.auto_send_enabled?'Выключить автоотправку':'Включить автоотправку'}</button><div class="preview-panel"><strong>Проверить правило на отзыве</strong><select id="settings-review">${state.rows.map(r=>`<option value="${esc(r.id)}" ${r.id===state.selected?.id?'selected':''}>${esc(r.id)} · ${esc((r.body||r.pros||'').slice(0,55))}</option>`).join('')}</select><button id="preview-settings" type="button">Показать результат</button><div id="settings-preview"></div></div></section></div>`;$('#rule-scope').value=s.scope_type==='all'?'all':s.scope_type+':'+s.scope_id;$('#rule-scope').onchange=e=>attempt(()=>{let [typ,id='']=e.target.value.split(':');return loadSettings(typ,id)});$('#preview-settings').onclick=()=>attempt(async()=>{let p=await api('/api/v4/preview','POST',{review_id:$('#settings-review').value,scope_type:s.scope_type,scope_id:s.scope_id,proposed_settings:readSettings()});$('#settings-preview').innerHTML=`<p><strong>${esc(p.status)}</strong> · ${esc(p.reason)}</p><p>${esc(p.text||'Нет текста')}</p><small>${esc(p.source||'')}</small>`});$('#toggle-autosend').onclick=()=>attempt(async()=>{let on=!state.settings.auto_send_enabled;await api('/api/v2/settings','PUT',{auto_send_enabled:on});notify(on?'Автоотправка включена':'Автоотправка выключена');await loadSettings(s.scope_type,s.scope_id);await loadQueue()});$('#template-settings').onclick=()=>attempt(openTemplates);$('#backlog-preview').onclick=()=>attempt(async()=>{let x=await api('/api/v4/backlog/preview?'+qs({scope_type:s.scope_type,scope_id:s.scope_id}));$('#backlog-result').innerHTML=`<p>${x.count}${x.capped?'+':''} обращений · пример: ${esc(x.sample.join(', ')||'нет')}</p><p>${esc(x.decision)}</p>${x.count?'<button id="backlog-reprepare" type="button">Переподготовить до 100</button>':''}`;$('#backlog-reprepare')?.addEventListener('click',()=>attempt(async()=>{let y=await api('/api/v4/backlog/reprepare','POST',{scope_type:s.scope_type,scope_id:s.scope_id});notify(y.detail);$('#backlog-preview').click();await loadQueue()}))});$('#settings-footer').innerHTML='<p>Накопленные обращения не уйдут автоматически после изменения правил.</p><span class="spacer"></span><button id="save-settings" class="primary" type="button">Сохранить правила</button>';$('#save-settings').onclick=()=>attempt(async()=>{let x=await api('/api/v4/settings','PUT',{scope_type:s.scope_type,scope_id:s.scope_id,expected_version:s.version,data:readSettings()});notify(x.detail);await loadSettings(s.scope_type,s.scope_id)})}
function readSettings(){return {generation_mode:$('input[name=generation]:checked').value,send_mode:$('input[name=send-mode]:checked').value,tone:$('#tone').value,length:$('#length').value,use_name:$('#use-name').checked,llm_budget_per_day:Number($('#budget').value),llm_max_per_cycle:Number($('#cycle-budget').value),only_new:$('#only-new').checked,rating_actions:Object.fromEntries($$('[data-rating]').map(x=>[x.dataset.rating,x.value])),exceptions:Object.fromEntries($$('[data-exception]').map(x=>[x.dataset.exception,x.checked]))}}
async function loadKnowledge(){state.knowledge=await api('/api/v4/knowledge?product_id='+encodeURIComponent(state.productKnowledge));renderKnowledge()}
function renderKnowledge(){let k=state.knowledge;let product=k.products.find(p=>p.product_id===state.productKnowledge)||k.products[0];state.productKnowledge=product.product_id;let facts=k.facts.filter(f=>f.status==='approved');let drafts=k.facts.filter(f=>f.status==='draft'||f.status==='conflict');let fieldLabels={composition:'Состав',wash:'Стирка',dry:'Сушка',iron:'Глажка',fit:'Посадка',measurement:'Измерения',feature:'Особенность',contents:'Комплектация'};let scenario=k.scenarios.find(x=>x.id===state.scenario)||k.scenarios[0];state.scenario=scenario.id;$('#settings-content').innerHTML=`<div class="settings-scope"><strong>Товар</strong><select id="knowledge-product">${productOptions(k.products,product.product_id)}</select><small>Источники и версии хранятся для каждого Demo сеанса отдельно.</small></div><div class="settings-grid"><section><h2>Проверенные факты</h2><p class="micro">В ответы попадают только утверждённые факты. Черновик и конфликт требуют решения менеджера.</p><div class="field-table">${facts.map(f=>`<div class="field-row"><strong>${fieldLabels[f.field]||esc(f.field)}<small>${esc(f.scope==='model'?'Модель':'Вариант')} · v${f.version}</small></strong><span>${esc(f.value)}<small>${esc(f.source)}</small></span><button type="button" data-edit-fact="${esc(f.field)}" title="Изменить факт">✎</button></div>`).join('')}</div>${drafts.length?`<h3>Черновики и конфликты</h3>${drafts.map(f=>`<div class="field-row draft"><strong>${esc(fieldLabels[f.field]||f.field)} · v${f.version}</strong><span>${esc(f.value)}<small>${esc(f.source)} · ${esc(f.excerpt)}</small></span><button type="button" data-apply="${esc(f.fact_key)}" data-version="${f.version}">Принять</button></div>`).join('')}`:''}<details><summary>История и откат</summary>${k.facts.filter(f=>f.status==='retired').map(f=>`<div class="field-row"><strong>${esc(fieldLabels[f.field]||f.field)} · v${f.version}</strong><span>${esc(f.value)}</span><button type="button" data-rollback="${esc(f.fact_key)}" data-version="${f.version}">Вернуть</button></div>`).join('')||'Нет прошлых версий'}</details><form id="fact-form" class="fact-form"><h3>Добавить факт</h3><div class="two-col"><label>Область<select name="scope"><option value="variant">Вариант товара</option><option value="model">Вся модель</option></select></label><label>Поле<select name="field">${Object.entries(fieldLabels).map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select></label></div><label>Значение<input name="value" required maxlength="700"></label><label>Источник<input name="source" required maxlength="700" placeholder="Карточка товара, инструкция продавца"></label><label>Точная цитата или основание<textarea name="excerpt" required maxlength="700"></textarea></label><button class="primary">Создать черновик</button></form><div class="inline-actions"><label>Импорт XLSX<input id="knowledge-file" type="file" accept=".xlsx"></label><button id="import-knowledge" type="button">Импортировать черновики</button></div><details><summary>Извлечь черновики через Hermes</summary><label>Название источника<input id="extract-source" placeholder="Инструкция по уходу"></label><label>Текст источника<textarea id="extract-text" minlength="20" maxlength="10000"></textarea></label><button id="extract-knowledge" type="button">Извлечь</button></details></section><section><h2>Опыт продавца</h2><p>Совет применяется к выбранным сценариям после проверки текста.</p><form id="advice-form"><label>Совет<textarea name="text" required maxlength="500">${esc(k.seller_advice[0]?.text||'')}</textarea></label><label>Источник<input name="source" required value="${esc(k.seller_advice[0]?.source||'Указание продавца')}"></label><div class="scenario-options">${k.scenarios.map(x=>`<label><input type="checkbox" name="advice-scenario" value="${esc(x.id)}" ${(k.seller_advice[0]?.applies_to||[]).includes(x.id)?'checked':''}>${esc(x.name)}</label>`).join('')}</div><button type="submit">Сохранить совет</button></form><h2>Сценарии ответа</h2><select id="scenario-select">${k.scenarios.map(x=>`<option value="${esc(x.id)}" ${x.id===scenario.id?'selected':''}>${esc(x.name)} · v${x.version}</option>`).join('')}</select><form id="scenario-form" class="scenario-form"><label class="check-row"><input name="enabled" type="checkbox" ${scenario.enabled?'checked':''}>Включён</label><label>Название<input name="name" value="${esc(scenario.name)}" required></label><label>Когда применять<input name="when" value="${esc(scenario.when)}" required></label><label>Цель<input name="goal" value="${esc(scenario.goal)}" required></label><label>Совет для ответа<textarea name="advice">${esc(scenario.advice)}</textarea></label><label>Ограничения<textarea name="restrictions">${esc(scenario.restrictions)}</textarea></label><label class="check-row"><input name="review_on_complaint" type="checkbox" ${scenario.review_on_complaint?'checked':''}>Жалобы направлять менеджеру</label><div class="scenario-options">${Object.entries(fieldLabels).map(([v,l])=>`<label><input type="checkbox" name="include" value="${v}" ${scenario.include.includes(v)?'checked':''}>${l}</label>`).join('')}</div><div class="inline-actions"><button class="primary" type="submit">Сохранить сценарий</button>${scenario.version>1?'<button id="undo-scenario" type="button">Вернуть предыдущую версию</button>':''}</div></form><div class="preview-panel scenario-preview"><strong>Предпросмотр ответа</strong><select id="knowledge-review">${state.rows.map(r=>`<option value="${esc(r.id)}">${esc(r.id)} · ${esc((r.body||'').slice(0,45))}</option>`).join('')}</select><button id="preview-knowledge" type="button">Проверить</button><div id="knowledge-preview"></div></div></section></div>`;$('#settings-footer').innerHTML='<p>Изменение знаний или сценария отзовёт старые разрешения на отправку.</p>';$('#knowledge-product').onchange=e=>attempt(async()=>{state.productKnowledge=e.target.value;await loadKnowledge()});$('#scenario-select').onchange=e=>{state.scenario=e.target.value;renderKnowledge()};$$('[data-edit-fact]').forEach(b=>b.onclick=()=>{let f=facts.find(x=>x.field===b.dataset.editFact);let form=$('#fact-form');form.elements.scope.value=f.scope;form.elements.field.value=f.field;form.elements.value.value=f.value;form.elements.source.value=f.source;form.elements.excerpt.value=f.excerpt||f.source;form.scrollIntoView({block:'nearest'})});$('#fact-form').onsubmit=e=>{e.preventDefault();attempt(async()=>{let f=e.target,scope=f.elements.scope.value;let x=await api('/api/v4/knowledge/facts','POST',{scope,owner_id:scope==='model'?product.model_id:product.product_id,field:f.elements.field.value,value:f.elements.value.value,source:f.elements.source.value,excerpt:f.elements.excerpt.value});notify(x.detail);await loadKnowledge()})};$$('[data-apply]').forEach(b=>b.onclick=()=>attempt(async()=>{let x=await api(`/api/v4/knowledge/facts/${encodeURIComponent(b.dataset.apply)}/apply?version=${b.dataset.version}`,'POST');notify(x.detail);await loadKnowledge()}));$$('[data-rollback]').forEach(b=>b.onclick=()=>attempt(async()=>{await api(`/api/v4/knowledge/facts/${encodeURIComponent(b.dataset.rollback)}/rollback?version=${b.dataset.version}`,'POST');notify('Прежнее значение восстановлено');await loadKnowledge()}));$('#scenario-form').onsubmit=e=>{e.preventDefault();attempt(async()=>{let f=e.target;let data={name:f.elements.name.value,enabled:f.elements.enabled.checked,when:f.elements.when.value,goal:f.elements.goal.value,include:[...f.querySelectorAll('[name=include]:checked')].map(x=>x.value),advice:f.elements.advice.value,restrictions:f.elements.restrictions.value,review_on_complaint:f.elements.review_on_complaint.checked};let x=await api('/api/v4/knowledge/scenarios/'+scenario.id,'PUT',{expected_version:scenario.version,data});notify(x.detail);await loadKnowledge()})};$('#undo-scenario')?.addEventListener('click',()=>attempt(async()=>{await api(`/api/v4/knowledge/scenarios/${scenario.id}/rollback?version=${scenario.version-1}`,'POST');notify('Сценарий восстановлен');await loadKnowledge()}));$('#advice-form').onsubmit=e=>{e.preventDefault();attempt(async()=>{let f=e.target;await api('/api/v4/knowledge/advice/'+product.model_id,'PUT',{expected_version:k.seller_advice[0]?.version||0,data:{text:f.elements.text.value,source:f.elements.source.value,applies_to:[...f.querySelectorAll('[name=advice-scenario]:checked')].map(x=>x.value)}});notify('Совет сохранён');await loadKnowledge()})};$('#import-knowledge').onclick=()=>attempt(async()=>{let file=$('#knowledge-file').files[0];if(!file)throw new Error('Выберите XLSX');let r=await fetch('/api/v4/knowledge/import',{method:'POST',body:await file.arrayBuffer()});let x=await r.json();if(!r.ok)throw new Error(x.detail);notify(x.detail);await loadKnowledge()});$('#extract-knowledge').onclick=()=>attempt(async()=>{let x=await api('/api/v4/knowledge/extract','POST',{product_id:product.product_id,source_text:$('#extract-text').value,source_name:$('#extract-source').value});notify(x.detail);await loadKnowledge()});$('#preview-knowledge').onclick=()=>attempt(async()=>{let x=await api('/api/v4/preview','POST',{review_id:$('#knowledge-review').value});$('#knowledge-preview').innerHTML=`<p>${esc(x.text||x.reason)}</p><small>${esc(x.source||'')} · ${esc(x.scenario||'')}</small>`})}
async function loadCampaigns(){state.campaigns=await api('/api/v4/campaigns');renderCampaigns()}
function campaignField(c,k){return c[k]??''}
function dateInput(ts){let d=new Date(ts*1000);let parts=Object.fromEntries(new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Moscow',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(d).map(x=>[x.type,x.value]));return `${parts.year}-${parts.month}-${parts.day}T${parts.hour}:${parts.minute}`}
function parseCampaignDate(value){return new Date(value+':00+03:00').getTime()/1000}
function campaignFormData(c){const f=$('#campaign-form');return {name:f.elements.name.value,status:f.elements.status.value,starts_at:parseCampaignDate(f.elements.starts_at.value),ends_at:parseCampaignDate(f.elements.ends_at.value),timezone:'Europe/Moscow',source_product_ids:[...f.querySelectorAll('[name=source-product]:checked')].map(x=>x.value),candidate_ids:[...f.querySelectorAll('[name=candidate]:checked')].map(x=>x.value),trigger:f.elements.trigger.value,mode:f.elements.mode.value,max_items:Number(f.elements.max_items.value),min_stock:Number(f.elements.min_stock.value),max_age_minutes:Number(f.elements.max_age_minutes.value),promo_only:f.elements.promo_only.checked,priority:Number(f.elements.priority.value),article_view:f.elements.article_view.value,jam_state:f.elements.jam_state.value,jam_source:f.elements.jam_source.value,exclude_complaints:f.elements.exclude_complaints.checked}}
function renderCampaigns(){let k=state.campaigns;let c=k.campaigns.find(x=>x.id===state.campaign)||k.campaigns[0];if(!c){$('#settings-content').innerHTML='<div class="empty">Кампаний пока нет</div>';return}state.campaign=c.id;let cs=k.candidates;$('#settings-content').innerHTML=`<div class="campaign-top"><div><strong>Сезонная кампания</strong><select id="campaign-select">${k.campaigns.map(x=>`<option value="${esc(x.id)}" ${x.id===c.id?'selected':''}>${esc(x.name)} · ${esc(x.status)}</option>`).join('')}</select><button id="new-campaign" type="button">Новая кампания</button></div><div><strong>Статус</strong><p>${esc(c.status)} · версия ${c.version}</p></div><div><strong>Источник</strong><p>${k.mode==='demo'?'Синтетические данные Demo':'Только собственные тестовые товары Sandbox'}</p></div></div><form id="campaign-form" class="campaign-form"><section><h2>Условия кампании</h2><label>Название<input name="name" value="${esc(c.name)}" required></label><div class="two-col"><label>Начало · МСК<input name="starts_at" type="datetime-local" value="${dateInput(c.starts_at)}" required></label><label>Окончание · МСК<input name="ends_at" type="datetime-local" value="${dateInput(c.ends_at)}" required></label></div><label>Статус<select name="status">${pick(c.status,[['draft','Черновик'],['active','Активна'],['paused','Пауза'],['finished','Завершена']])}</select></label><label>Исходные товары</label><div class="product-checks">${k.products.map(p=>`<label><input name="source-product" value="${esc(p.product_id)}" type="checkbox" ${c.source_product_ids.includes(p.product_id)?'checked':''}><img src="${esc(p.photo)}" alt="">${esc(p.name)}<small>${esc(p.color)}</small></label>`).join('')}</div><label>Повод для подбора<select name="trigger">${pick(c.trigger,[['softness','Похвала мягкости'],['fit','Похвала посадке'],['look','Образ и сочетание'],['any_positive','Любой позитивный контекст']])}</select></label><label>Режим<select name="mode">${pick(c.mode,[['alternatives','Дополнения и альтернативы'],['kit','Полный комплект']])}</select></label><div class="two-col"><label>Не более товаров в ответе<select name="max_items">${pick(c.max_items,[[1,'1 товар'],[2,'2 товара']])}</select></label><label>Приоритет<input name="priority" type="number" min="0" max="100" value="${c.priority}"></label></div><label class="check-row"><input name="promo_only" type="checkbox" ${c.promo_only?'checked':''}>Только во время подтверждённой акции</label><label class="check-row"><input name="exclude_complaints" type="checkbox" ${c.exclude_complaints?'checked':''}>Исключать жалобы и вопросы</label><div class="two-col"><label>Минимальный остаток<input name="min_stock" type="number" min="1" max="20" value="${c.min_stock}"></label><label>Возраст снимка, мин<input name="max_age_minutes" type="number" min="1" max="1440" value="${c.max_age_minutes}"></label></div><h3>Артикул в ответе</h3><label>Предпросмотр<select name="article_view">${pick(c.article_view,[['text','Номер текстом'],['clickable_preview','Ожидаемая кликабельность · только Demo']])}</select></label><label>Опция WB<select name="jam_state">${pick(c.jam_state,[['unknown','Не проверена'],['available','Продавец подтвердил доступность'],['unavailable','Недоступна']])}</select></label><label>Основание статуса<input name="jam_source" value="${esc(c.jam_source)}" required></label><p class="campaign-note">Кликабельность формирует WB. Переключатель меняет только предпросмотр и не включает подписку в кабинете.</p><div class="inline-actions"><button class="primary" type="submit">Сохранить кампанию</button>${k.mode==='demo'?'<button id="refresh-candidates" type="button">Обновить учебный снимок</button>':''}</div></section><section><h2>Товары для рекомендации · ${c.candidate_ids.length}</h2><p class="micro">Кандидаты, размер и остатки проверяются повторно перед отправкой.</p><div class="candidate-checks">${cs.map(x=>`<label><input type="checkbox" name="candidate" value="${esc(x.id)}" ${c.candidate_ids.includes(x.id)?'checked':''}><img src="${esc(x.photo)}" alt="">${esc(x.name)} · ${esc(x.sizes.join('/'))}</label>`).join('')}</div><details class="candidate-editor"><summary>Редактор кандидата</summary><select id="candidate-select">${cs.map(x=>`<option value="${esc(x.id)}">${esc(x.name)} · ${esc(x.id)}</option>`).join('')}</select><button id="new-candidate" type="button">Добавить товар</button><div id="candidate-fields"></div></details><h2>Проверка отбора</h2><label>Тестовый отзыв<input id="campaign-review" value="R001" list="campaign-review-list" placeholder="ID отзыва"></label><datalist id="campaign-review-list">${state.rows.map(x=>`<option value="${esc(x.id)}">${esc((x.body||x.pros||'').slice(0,50))}</option>`).join('')}</datalist><button id="preview-campaign" type="button">Показать отбор</button><div id="campaign-result" class="preview-panel"><p>Выберите отзыв и запустите проверку.</p></div></section></form>`;$('#settings-footer').innerHTML='<p>Нет свежих подходящих кандидатов — коммерческий фрагмент не добавляется. Старые ответы не изменяются.</p>';$('#campaign-select').onchange=e=>{state.campaign=e.target.value;renderCampaigns()};$('#campaign-form').onsubmit=e=>{e.preventDefault();attempt(async()=>{let x=await api('/api/v4/campaigns/'+encodeURIComponent(c.id),'PUT',{expected_version:c.version,data:campaignFormData(c)});notify(x.detail);await loadCampaigns()})};$('#refresh-candidates')?.addEventListener('click',()=>attempt(async()=>{let x=await api(`/api/v4/campaigns/${c.id}/refresh-demo`,'POST');notify(x.detail);await loadCampaigns()}));$('#candidate-select').onchange=renderCandidateEditor;renderCandidateEditor();$('#new-campaign').onclick=()=>attempt(async()=>{let name=prompt('Название новой кампании');if(!name?.trim())return;let id='campaign-'+crypto.randomUUID().slice(0,8);let data={...c,name:name.trim(),status:'draft'};delete data.id;delete data.version;let x=await api('/api/v4/campaigns/'+id,'PUT',{expected_version:0,data});state.campaign=id;notify(x.detail);await loadCampaigns()});$('#new-candidate').onclick=renderNewCandidateEditor;$('#preview-campaign').onclick=()=>attempt(async()=>{let rid=$('#campaign-review').value;if(!rid)throw new Error('Выберите тестовый отзыв из очереди');let x=await api(`/api/v4/campaigns/${c.id}/preview?review_id=${encodeURIComponent(rid)}`);renderCampaignResult(x)})}
function renderCampaignResult(x){let s=x.selection;$('#campaign-result').innerHTML=`<strong>${s.candidate_count} кандидатов → ${s.eligible_count} подходят → ${s.selected.length} в ответе</strong><p>${esc(s.reason)}</p>${s.selected.map(v=>`<div class="candidate-preview"><img src="${esc(v.photo)}" alt=""><span><strong>${esc(v.name)} · артикул WB <span class="${s.campaign?.article_view==='clickable_preview'?'article-expected':''}">${v.article}</span></strong><small>${esc(v.reason)} · размер ${esc(v.size)} · остаток ${v.stock_for_size}</small></span><span class="tag">В ответе</span></div>`).join('')}${s.reserve.map(v=>`<div class="candidate-preview"><img src="${esc(v.photo)}" alt=""><span><strong>${esc(v.name)}</strong><small>Подходит, резерв · размер ${esc(v.size)}</small></span></div>`).join('')}<details><summary>Почему исключены остальные · ${s.excluded.length}</summary><ul>${s.excluded.map(v=>`<li>${esc(v.id)}: ${esc(v.reason)}</li>`).join('')}</ul></details><p><strong>Ответ:</strong> ${esc(x.answer||'Нет подготовленного текста')}</p><small>${esc(x.article_preview)}</small>`}
async function loadProposals(){state.proposals=await api('/api/v4/proposals');renderProposals()}
function renderProposals(){let k=state.proposals;let p=k.proposals.find(x=>x.id===state.proposal)||k.proposals[0];state.proposal=p?.id||null;$('#proposal-count').textContent=k.proposals.filter(x=>x.status==='pending').length;$('#settings-content').innerHTML=`<div class="settings-scope"><strong>Анализ обращений</strong><select id="proposal-product">${productOptions(k.products,state.productKnowledge)}</select><select id="proposal-days">${pick(7,[[7,'7 дней'],[30,'30 дней'],[90,'90 дней']])}</select><button id="analyze-proposals" type="button">Найти предложения</button></div><div class="settings-grid"><section class="proposal-list"><h2>Предложения ИИ</h2><p class="micro">Только собственные обращения тестовой базы. До принятия правила не меняются.</p>${k.proposals.map(x=>`<button class="proposal-card ${x.id===p?.id?'active':''}" data-proposal="${esc(x.id)}"><strong>${esc(x.title)}</strong><small>${esc(x.product_id)} · ${x.group_count} из ${x.denominator} обращений · ${esc(x.status||'pending')}</small></button>`).join('')||'<p>Предложений пока нет. Запустите ограниченный анализ.</p>'}<details><summary>Выгрузка конкурентов · отдельно от фактов товара</summary><label>Имя CSV<input id="competitor-name" value="competitors.csv"></label><label>CSV<textarea id="competitor-csv"></textarea></label><button id="import-competitor" type="button">Загрузить как гипотезы</button></details></section><section class="proposal-detail">${p?`<h2>${esc(p.title)}</h2><p>${esc(p.hypothesis)}</p><strong>Наблюдения · ${p.group_count} из ${p.denominator}</strong>${p.evidence.map(x=>`<div class="evidence-row"><strong>${esc(x.id)}</strong> · ${esc(x.quote)} · ${x.rating}★</div>`).join('')}<label>Предлагаемая правка<textarea id="proposal-advice" maxlength="300">${esc(p.proposed_advice)}</textarea></label><div class="proposal-comparison"><div><strong>До</strong>${esc(p.before||'—')}</div><div><strong>После</strong>${esc(p.after||'—')}</div></div><button id="proposal-examples" type="button">Проверить на примерах</button><div id="proposal-example-result"></div>${p.status==='pending'?`${p.validation_error?`<div class="warning-box">Предложение не прошло текущую проверку: ${esc(p.validation_error)}. Измените текст перед принятием.</div>`:''}<div class="proposal-controls"><button id="reject-proposal" type="button">Отклонить</button><button id="save-proposal" type="button">Сохранить правку</button><button id="accept-proposal" class="primary" type="button" ${p.validation_error?'disabled':''}>Принять</button></div>`:'<p class="status-note">Предложение уже обработано.</p>'}`:'<div class="empty">Выберите предложение после анализа</div>'}</section></div>`;$('#settings-footer').innerHTML='<p>Hermes предлагает текст. Только менеджер меняет действующий сценарий.</p>';$('#proposal-product').onchange=e=>state.productKnowledge=e.target.value;$('#analyze-proposals').onclick=()=>attempt(async()=>{let x=await api('/api/v4/proposals/analyze','POST',{product_id:$('#proposal-product').value,days:Number($('#proposal-days').value)});notify(x.detail);await loadProposals()});$$('[data-proposal]').forEach(b=>b.onclick=()=>{state.proposal=b.dataset.proposal;renderProposals()});$('#import-competitor').onclick=()=>attempt(async()=>{let x=await api('/api/v4/proposals/competitor-import','POST',{filename:$('#competitor-name').value,csv_text:$('#competitor-csv').value});notify(x.detail)});if(!p)return;$('#proposal-examples').onclick=()=>attempt(async()=>{let x=await api(`/api/v4/proposals/${p.id}/examples`);$('#proposal-example-result').innerHTML=x.examples.map(e=>`<div class="evidence-row">${esc(JSON.stringify(e))}</div>`).join('')});$('#save-proposal')?.addEventListener('click',()=>attempt(async()=>{await api(`/api/v4/proposals/${p.id}`,'PUT',{advice:$('#proposal-advice').value});notify('Правка сохранена');await loadProposals()}));$('#accept-proposal')?.addEventListener('click',()=>attempt(async()=>{if($('#proposal-advice').value!==p.proposed_advice)await api(`/api/v4/proposals/${p.id}`,'PUT',{advice:$('#proposal-advice').value});let x=await api(`/api/v4/proposals/${p.id}/accept`,'POST');notify(x.detail);await loadProposals()}));$('#reject-proposal')?.addEventListener('click',()=>attempt(async()=>{let x=await api(`/api/v4/proposals/${p.id}/reject`,'POST');notify(x.detail);await loadProposals()}))}
$$('.entity-nav button').forEach(b=>b.onclick=()=>attempt(async()=>{state.kind=b.dataset.kind;state.offset=0;state.product='';state.rating=0;$$('.entity-nav button').forEach(x=>x.classList.toggle('active',x===b));await loadQueue(false);setView('queue')}));$$('.queue-tabs button').forEach(b=>b.onclick=()=>attempt(async()=>{state.tab=b.dataset.tab;state.offset=0;await loadQueue(false)}));$('#queue-product').onchange=e=>attempt(async()=>{state.product=e.target.value;state.offset=0;await loadQueue(false)});$('#queue-rating').onchange=e=>attempt(async()=>{state.rating=Number(e.target.value);state.offset=0;await loadQueue(false)});$('#queue-sort').onchange=e=>attempt(async()=>{state.sort=e.target.value;state.offset=0;await loadQueue(false)});$('#queue-search').oninput=e=>{clearTimeout(state.searchTimer);state.searchTimer=setTimeout(()=>attempt(async()=>{state.q=e.target.value;state.offset=0;await loadQueue(false)}),250)};$('#prev-page').onclick=()=>attempt(async()=>{state.offset=Math.max(0,state.offset-state.limit);await loadQueue(false)});$('#next-page').onclick=()=>attempt(async()=>{state.offset+=state.limit;await loadQueue(false)});$('#open-settings').onclick=()=>attempt(()=>showSettings());$('#settings-back').onclick=()=>{setView('queue');attempt(()=>loadQueue())};$$('.settings-tabs button').forEach(b=>b.onclick=()=>attempt(()=>showSettings(b.dataset.section)));$('#auto-pause').onclick=()=>attempt(async()=>{let next=!state.processing;await api('/api/v2/settings','PUT',{processing_enabled:next,auto_send_enabled:state.auto});notify(next?'Подготовка возобновлена':'Обработка поставлена на паузу');await loadQueue()});$('#photo-close').onclick=()=>$('#photo-dialog').close();$('#template-close').onclick=()=>$('#template-dialog').close();$('#template-form').onsubmit=e=>{e.preventDefault();attempt(async()=>{let f=e.target;await api('/api/v2/templates','POST',{name:$('#template-name').value,kind:$('#template-kind').value,intent:$('#template-intent').value,body:$('#template-body').value});notify('Шаблон сохранён');await openTemplates()})};$('#defer-dialog').addEventListener('close',()=>{if($('#defer-dialog').returnValue!=='confirm')return;attempt(async()=>{let r=state.selected;await api('/api/v2/reviews/'+encodeURIComponent(r.id)+'/defer','POST',{reason:$('#defer-reason').value});notify('Обращение отложено');$('#defer-reason').value='';await loadQueue(false)})});attempt(()=>loadQueue(false));
setInterval(()=>{if(!state.rows.length&&state.summary?.processing>0&&!$('#queue-view').hidden)attempt(()=>loadQueue(false))},3000);
function relationFields(relations={}){return `<div class="field-table"><strong>Связь с исходными товарами</strong><p class="micro">Добавьте короткое подтверждённое основание. Фото или категория сами по себе не доказывают совместимость.</p>${state.campaigns.products.map(p=>`<label class="field-row"><span>${esc(p.name)} · ${esc(p.color)}</span><input data-relation="${esc(p.product_id)}" value="${esc(relations[p.product_id]||'')}" placeholder="Основание или пусто"></label>`).join('')}</div>`}
function readRelations(){return Object.fromEntries($$('[data-relation]').map(x=>[x.dataset.relation,x.value.trim()]).filter(([,v])=>v))}
function renderCandidateEditor(){let x=state.campaigns.candidates.find(v=>v.id===$('#candidate-select').value);$('#candidate-fields').innerHTML=`<div class="candidate-preview"><img src="${esc(x.photo)}" alt=""><span><strong>${esc(x.name)}</strong><small>Артикул WB ${x.nm_id} · ${esc(x.source)}</small></span></div><div class="two-col"><label>Название<input id="candidate-name" value="${esc(x.name)}"></label><label>Размеры (через запятую)<input id="candidate-sizes" value="${esc(x.sizes.join(', '))}"></label><label>Остаток первого размера<input id="candidate-stock" type="number" min="0" value="${x.stock[x.sizes[0]]||0}"></label><label>Приоритет<input id="candidate-priority" type="number" min="0" max="100" value="${x.priority}"></label></div><label class="check-row"><input id="candidate-approved" type="checkbox" ${x.approved?'checked':''}>Товар утверждён для подбора</label><label>WB Sandbox nmID собственной тестовой карточки<input id="candidate-sandbox" type="number" min="1" value="${x.sandbox_nm_id||''}" placeholder="Нет сопоставления"></label>${relationFields(x.relations)}<button id="save-candidate" type="button">Сохранить кандидата</button>`;$('#save-candidate').onclick=()=>attempt(async()=>{let sizes=$('#candidate-sizes').value.split(',').map(x=>x.trim()).filter(Boolean);if(!sizes.length)throw new Error('Укажите размер');let stock={...x.stock};stock[sizes[0]]=Number($('#candidate-stock').value);let data={...x,name:$('#candidate-name').value.trim(),sizes,stock,approved:$('#candidate-approved').checked,priority:Number($('#candidate-priority').value),sandbox_nm_id:$('#candidate-sandbox').value?Number($('#candidate-sandbox').value):null,relations:readRelations()};delete data.id;let y=await api('/api/v4/candidates/'+encodeURIComponent(x.id),'PUT',{data});notify(y.detail);await loadCampaigns()})}
function renderNewCandidateEditor(){let photos=[...new Set([...state.campaigns.products,...state.campaigns.candidates].map(x=>x.photo))];$('#candidate-fields').innerHTML=`<h3>Новый товар для подбора</h3><div class="two-col"><label>Название<input id="new-name" required></label><label>Артикул WB Demo<input id="new-nmid" type="number" min="1" required></label><label>Категория<input id="new-category" required></label><label>Размер<input id="new-size" placeholder="M" required></label><label>Остаток<input id="new-stock" type="number" min="0" value="0"></label><label>Фото<select id="new-photo">${photos.map(x=>`<option value="${esc(x)}">${esc(x.split('/').pop())}</option>`).join('')}</select></label></div><label>Источник снимка<input id="new-source" value="Введено продавцом в Demo; не WB"></label><label>Теги через запятую<input id="new-tags" value="softness, look"></label>${relationFields()}<button id="save-new-candidate" type="button">Добавить в каталог</button>`;$('#save-new-candidate').onclick=()=>attempt(async()=>{let size=$('#new-size').value.trim(),nm=Number($('#new-nmid').value),name=$('#new-name').value.trim();if(!size||!nm||!name)throw new Error('Заполните название, артикул и размер');let now=Date.now()/1000;let data={name,nm_id:nm,sandbox_nm_id:null,photo:$('#new-photo').value,category:$('#new-category').value.trim(),tags:$('#new-tags').value.split(',').map(x=>x.trim()).filter(Boolean),sizes:[size],stock:{[size]:Number($('#new-stock').value)},promo_start:now-3600,promo_end:now+86400,snapshot_at:now,source:$('#new-source').value.trim(),approved:false,priority:0,relations:readRelations(),kit_id:null};let id='NEW-'+crypto.randomUUID().slice(0,8);let x=await api('/api/v4/candidates/'+id,'PUT',{data});notify(x.detail+' Отметьте его в списке кандидатов и сохраните кампанию.');await loadCampaigns()})}
